package com.wizzadrds.theworldremembers.behavior; import net.minecraft.core.BlockPos; import java.util.UUID; public record NpcTravelState(UUID npcId,BlockPos origin,BlockPos destination,long startedTick,long lastObservedTick,double distance){public NpcTravelState observe(BlockPos current,long tick){return new NpcTravelState(npcId,origin,destination,startedTick,tick,current.distSqr(origin));} public long elapsed(long tick){return Math.max(0,tick-startedTick);}}